// Extract phone number, message text, and property code from OpenWA webhook payload
const entry = $input.first().json;

// OpenWA sends body.data for message.received events
const dataObj = entry.body?.data || entry.data || entry.payload || entry.message || entry;

// Extract raw sender and text safely
let rawFrom = dataObj.from || dataObj.sender?.id || dataObj.chatId || entry.from || '';
let rawText = dataObj.body || dataObj.text || dataObj.content || (typeof dataObj.message === 'string' ? dataObj.message : '') || '';

// Safely ensure text is a string
let text = typeof rawText === 'string' ? rawText : String(rawText || '');

// Extract actual user phone number (resolving @lid JIDs to real @c.us phone numbers)
let phone = '';

if (dataObj.sender?.phone) {
  phone = String(dataObj.sender.phone).replace(/[^0-9]/g, '');
}

if (!phone || phone.length > 13) {
  const jidCandidates = [
    dataObj.author,
    dataObj.sender?.id,
    dataObj.chat?.contact?.id,
    dataObj.from,
    dataObj.chatId,
    entry.from
  ];

  for (const candidate of jidCandidates) {
    if (typeof candidate === 'string' && candidate.includes('@c.us')) {
      const extracted = candidate.replace(/@.*$/, '').replace(/[^0-9]/g, '');
      if (extracted && extracted.length <= 13) {
        phone = extracted;
        break;
      }
    }
  }
}

if (!phone) {
  phone = rawFrom.replace(/@.*$/, '').replace(/[^0-9]/g, '');
}

let propertyCode = null;

const refMatch = text.match(/(?:Ref|Reference|Code):?\s*([A-Z0-9-]+)\b/i);
if (refMatch) {
  propertyCode = refMatch[1].toUpperCase().replace(/[^A-Z0-9-]/g, '');
} else {
  const codeMatch = text.match(/\b(PROP-[A-Z0-9-]+|[A-Z]{2,4}\d{3,6})\b/i);
  if (codeMatch) {
    propertyCode = codeMatch[1].toUpperCase();
  }
}

return [{
  json: {
    phone_number: phone,
    raw_chat_id: rawFrom.includes('@') ? rawFrom : `${phone}@c.us`,
    message_text: text,
    property_code: propertyCode,
    session_id: `${phone}_${propertyCode || 'unknown'}`
  }
}];

// Recover property code from active session if message text did not contain one
const extracted = $('Extract Property Code').first().json;
const activeSession = $input.first().json;

let finalPropertyCode = extracted.property_code;
let finalSessionId = extracted.session_id;
let isNewEnquiry = false;

const activeCode = (activeSession?.property_code || '').trim().toUpperCase();
const newCode = (extracted?.property_code || '').trim().toUpperCase();

if (newCode && (!activeCode || activeCode !== newCode)) {
  isNewEnquiry = true;
  finalPropertyCode = newCode;
} else if (!finalPropertyCode && activeCode) {
  finalPropertyCode = activeCode;
  finalSessionId = activeSession.session_id || `${extracted.phone_number}_${activeCode}`;
  isNewEnquiry = false;
}

return [{
  json: {
    phone_number: extracted.phone_number,
    message_text: extracted.message_text,
    property_code: finalPropertyCode || null,
    session_id: finalSessionId,
    is_new_enquiry: isNewEnquiry
  }
}];

// Strip intent token from reply, capture intent flag
const raw = $input.first().json.output || '';
const confirmed = raw.includes('[INTENT:CONFIRMED]');
const cleanText = raw.replace(/\[INTENT:(CONFIRMED|OPEN)\]/g, '').trim();

return [{
  json: {
    ...$('Resolve Property Code').first().json,
    reply_text: cleanText,
    intent_confirmed: confirmed
  }
}];

parameters.query:
SELECT message FROM chat_sessions_memory
WHERE session_id = '{{ $('Resolve Property Code').first().json.session_id }}'
ORDER BY id ASC;

parameters.jsCode:
// Combine all transcript items into 1 single output item
const allItems = $input.all();
const messages = allItems.map(item => {
  const msg = item.json.message;
  if (!msg) return '';
  if (typeof msg === 'string') return msg;
  if (msg.data?.content) return `${msg.type || 'chat'}: ${msg.data.content}`;
  return JSON.stringify(msg);
}).filter(Boolean);

return [{
  json: {
    transcript_text: messages.join('\n')
  }
}];

// Parse Gemini's JSON summary output, guard against markdown fences
const first = $input.first().json;
const raw = typeof first === 'string' ? first : (first.text || first.content?.[0]?.text || first.output || JSON.stringify(first));
const clean = raw.replace(/```json|```/g, '').trim();

let parsed;
try {
  parsed = JSON.parse(clean);
} catch (e) {
  parsed = { summary: clean, outcome: 'no', next_step: 'Review manually - parse failed' };
}

return [{
  json: {
    ...$('Parse Intent Token').first().json,
    summary: parsed.summary,
    outcome: parsed.outcome,
    next_step: parsed.next_step
  }
}];

parameters.query:
UPDATE chat_sessions
SET status = 'closed', outcome = '{{ $json.outcome || 'no' }}', summary = '{{ ($json.summary || '').replace(/'/g, "''") }}', updated_at = now()
WHERE session_id = '{{ $('Resolve Property Code').first().json.session_id }}';

parameters.text:
=Summarize this WhatsApp leasing conversation transcript into a JSON object.

Transcript:
{{ $json.transcript_text }}

Return ONLY a raw valid JSON object with no extra text or markdown formatting outside the JSON, matching this schema:
{
  "summary": "Short 1-2 sentence summary of the inquiry",
  "outcome": "yes" or "no",
  "next_step": "Next action for leasing team"
}

